parameters.jsCode:
// Extrae las interacciones recibidas desde la UI de Streamlit o petición HTTP
const body = $json.body || $json;
const items = body.interacciones || body.data || (Array.isArray(body) ? body : [body]);

if (!items || items.length === 0) {
  throw new Error('No se recibieron interacciones en el body de la petición');
}

return items.map(item => ({ json: item }));

